-- Saved commutes and vehicles: privacy fields (M-18).
-- Spec: docs/superpowers/specs/2026-10-08-commute-privacy-design.md.
--
-- Exact origin and destination points stay owner-only (0004). What others may
-- later see is a generalized area: a 402 m circle (0.5 mi wide) around a
-- center drawn once at a uniformly random spot within 402 m of the exact point,
-- stored, and reused while the pin stays inside it. Each area is labelled from
-- its center (never the pin) with open boundary data in place_boundaries.

-- Commute saving was out of scope until now, so the hosted table should be
-- empty. New not-null columns would need a backfill if it isn't.
do $$
begin
  if exists (select 1 from public.commutes) then
    raise exception '0008 expects no saved commutes; add a backfill for the new columns first';
  end if;
end
$$;

-- Secure random bytes for drawing area centers. Already present on hosted Supabase.
create extension if not exists pgcrypto with schema extensions;

-- Boundary reference data ------------------------------------------------------

-- Neighborhood and city polygons used only to label areas. Open data, but the
-- app doesn't need it (labels are stored on the commute), so clients can
-- neither read nor write it. Geometry, not geography: the only lookup is
-- point-in-polygon, which a planar GiST index answers exactly.
create table public.place_boundaries (
  id text primary key,
  kind text not null check (kind in ('neighborhood','city')),
  name text not null,
  city text not null,
  geom extensions.geometry(MultiPolygon, 4326) not null,
  source text not null,
  license text not null
);

create index place_boundaries_geom_idx on public.place_boundaries using gist (geom);

alter table public.place_boundaries enable row level security;
revoke all on public.place_boundaries from public, anon, authenticated;

