-- END GENERATED place_boundaries

-- Area helpers -----------------------------------------------------------------

-- Area radius in meters: 0.25 mi, so an area is about 0.5 mi wide.
create function public.area_radius_m()
returns double precision
language sql
immutable
set search_path = ''
as $$
  select 402::double precision
$$;

-- D-16: is a pickup spot inside an area? Uses the area center, never an exact point.
create function public.within_area(area extensions.geography, spot extensions.geography)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select extensions.st_dwithin(spot, area, public.area_radius_m())
$$;

-- A center at a uniformly random spot in the disk of radius R around pin
-- (distance R·sqrt(u), so draws aren't bunched in the middle). Uses pgcrypto,
-- not random(): people see their own draws, and random()'s generator state
-- can be rebuilt from its outputs. 1 m under R so rounding can't push the pin
-- outside its area.
create function public.random_area_center(pin extensions.geography)
returns extensions.geography
language plpgsql
volatile
set search_path = ''
as $$
declare
  b bytea := extensions.gen_random_bytes(14);
  u double precision := ('x' || encode(substring(b from 1 for 7), 'hex'))::bit(56)::bigint / 72057594037927936.0;
  v double precision := ('x' || encode(substring(b from 8 for 7), 'hex'))::bit(56)::bigint / 72057594037927936.0;
begin
  return extensions.st_project(pin, (public.area_radius_m() - 1) * sqrt(u), 2 * pi() * v);
end
$$;

-- The area for a new or moved pin: an existing area of the same owner that
-- already contains it (oldest commute first, then this row's other area), or
-- a fresh draw. Reuse means one place never gets two independent circles,
-- which a viewer could intersect. Runs as the caller, so RLS limits the
-- lookup to the caller's own commutes.
create function public.commute_area_for(
  for_owner uuid, self_id uuid, pin extensions.geography, sibling extensions.geography
)
returns extensions.geography
language plpgsql
volatile
set search_path = ''
as $$
declare
  r double precision := public.area_radius_m();
  center extensions.geography;
begin
  select s.area into center
  from (
    select c.origin_area as area, c.created_at, c.id, 1 as slot
    from public.commutes c
    where c.owner_id = for_owner and c.id is distinct from self_id
    union all
    select c.destination_area, c.created_at, c.id, 2
    from public.commutes c
    where c.owner_id = for_owner and c.id is distinct from self_id
  ) s
  where s.area is not null and extensions.st_dwithin(pin, s.area, r)
  order by s.created_at, s.id, s.slot
  limit 1;

  if center is null and sibling is not null and extensions.st_dwithin(pin, sibling, r) then
    center := sibling;
  end if;

  return coalesce(center, public.random_area_center(pin));
end
$$;

-- The label for an area center: the neighborhood covering it, else the city,
-- else "San Francisco" or "East Bay" by the nearest city. Reads
-- place_boundaries, which clients can't, so it runs as its owner. It only ever
-- returns labels derived from public boundary data.
create function public.area_label(center extensions.geography)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select b.name || ' area, ' || b.city
     from public.place_boundaries b
     where b.kind = 'neighborhood'
       and extensions.st_covers(b.geom, center::extensions.geometry)
     order by extensions.st_area(b.geom), b.id
     limit 1),
    (select b.city
     from public.place_boundaries b
     where b.kind = 'city'
       and extensions.st_covers(b.geom, center::extensions.geometry)
     order by extensions.st_area(b.geom), b.id
     limit 1),
    (select case when b.city = 'San Francisco' then 'San Francisco' else 'East Bay' end
     from public.place_boundaries b
     where b.kind = 'city'
     order by b.geom operator(extensions.<->) center::extensions.geometry, b.id
     limit 1),
    'East Bay'
  )
$$;

-- Commutes ---------------------------------------------------------------------

alter table public.commutes
  alter column weekdays drop default,
  add column origin_area extensions.geography(point, 4326) not null,
  add column destination_area extensions.geography(point, 4326) not null,
  add column origin_area_label text not null,
  add column destination_area_label text not null,
  add column seats_offered integer,
  add column brings_scooter boolean not null default false,
  -- ISO weekdays Monday–Friday, non-empty, one-dimensional, no nulls.
  add constraint commutes_weekdays_iso check (
    cardinality(weekdays) > 0
    and array_ndims(weekdays) = 1
    and weekdays <@ array[1,2,3,4,5]
  ),
  add constraint commutes_departure_whole_minute check (extract(second from departure_time) = 0),
  add constraint commutes_timezone_la check (timezone = 'America/Los_Angeles'),
  add constraint commutes_seats_offered_range check (seats_offered between 1 and 8),
  add constraint commutes_driver_offers_seats check ((role = 'driver') = (seats_offered is not null)),
  -- Not "driver has a vehicle": deleting a vehicle sets vehicle_id to null (0004).
  add constraint commutes_passenger_no_vehicle check (role = 'driver' or vehicle_id is null),
  add constraint commutes_scooter_passenger_only check (role = 'passenger' or not brings_scooter);

-- One driver commute and one passenger commute per person ("Both" = two rows).
create unique index commutes_one_per_role on public.commutes (owner_id, role);

comment on column public.commutes.origin_area is
  'Generalized origin: center of a 402 m circle containing the exact point. Server-set.';
comment on column public.commutes.destination_area is
  'Generalized destination: center of a 402 m circle containing the exact point. Server-set.';
comment on column public.commutes.origin_area_label is
  'Label for origin_area, from place_boundaries at its center. Server-set.';
comment on column public.commutes.destination_area_label is
  'Label for destination_area, from place_boundaries at its center. Server-set.';
comment on column public.commutes.brings_scooter is
  'Passenger brings one foldable scooter within 120 x 50 x 60 cm and 20 kg (D-04).';

-- Weekdays are stored sorted and de-duplicated. Anything malformed (2-D, nulls)
-- is left alone for the check constraint to reject.
create function public.commutes_normalize()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.weekdays is not null
     and array_ndims(new.weekdays) = 1
     and array_position(new.weekdays, null) is null then
    new.weekdays := array(select distinct d from unnest(new.weekdays) as d order by d);
  end if;
  return new;
end
$$;

-- Areas and labels are always set here; values sent by the client are ignored.
-- An area (and its label) stays while its pin stays inside it.
create function public.commutes_set_areas()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  r double precision := public.area_radius_m();
begin
  if tg_op = 'UPDATE' and old.origin_area is not null
     and extensions.st_dwithin(new.origin, old.origin_area, r) then
    new.origin_area := old.origin_area;
    new.origin_area_label := old.origin_area_label;
  else
    new.origin_area := public.commute_area_for(
      new.owner_id, new.id, new.origin,
      case when tg_op = 'UPDATE' then old.destination_area end);
    new.origin_area_label := public.area_label(new.origin_area);
  end if;

  if tg_op = 'UPDATE' and old.destination_area is not null
     and extensions.st_dwithin(new.destination, old.destination_area, r) then
    new.destination_area := old.destination_area;
    new.destination_area_label := old.destination_area_label;
  else
    new.destination_area := public.commute_area_for(new.owner_id, new.id, new.destination, new.origin_area);
    new.destination_area_label := public.area_label(new.destination_area);
  end if;

  return new;
end
$$;

-- A driver can't offer more seats than the linked vehicle has. The composite
-- key (0004) makes it the same owner's vehicle, so RLS lets the caller read it.
create function public.commutes_check_seats()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  seats integer;
begin
  if new.vehicle_id is not null and new.seats_offered is not null then
    select v.passenger_seats into seats
    from public.vehicles v
    where v.id = new.vehicle_id;
    if seats is not null and new.seats_offered > seats then
      raise exception 'You offered more seats than your car has (%)', seats
        using errcode = '23514';
    end if;
  end if;
  return new;
end
$$;

create trigger commutes_normalize
  before insert or update on public.commutes
  for each row execute function public.commutes_normalize();

create trigger commutes_set_areas
  before insert or update on public.commutes
  for each row execute function public.commutes_set_areas();

create trigger commutes_check_seats
  before insert or update on public.commutes
  for each row execute function public.commutes_check_seats();

-- Vehicles ---------------------------------------------------------------------

update public.vehicles set color = nullif(btrim(color), '') where color is not null;

alter table public.vehicles
  add column plate text,
  add constraint vehicles_plate_format check (plate ~ '^[A-Z0-9]{2,8}$'),
  add constraint vehicles_color_length check (char_length(color) between 1 and 30);

comment on column public.vehicles.plate is
  'Licence plate, uppercase letters and digits. Owner-only; revealed to the matched rider after confirmation.';
comment on column public.vehicles.accepts_foldable_scooters is
  'The trunk fits one foldable scooter within 120 x 50 x 60 cm and 20 kg (D-04).';

-- Plate: uppercase, no spaces or dashes. Color: trimmed, blank becomes null.
create function public.vehicles_normalize()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.plate := nullif(upper(regexp_replace(new.plate, '[[:space:]-]', '', 'g')), '');
  new.color := nullif(btrim(new.color), '');
  return new;
end
$$;

-- Fewer seats in the car lowers the offer on that car's commutes to match.
create function public.vehicles_clamp_seats()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.passenger_seats < old.passenger_seats then
    update public.commutes c
    set seats_offered = new.passenger_seats
    where c.vehicle_id = new.id
      and c.seats_offered > new.passenger_seats;
  end if;
  return null;
end
$$;

create trigger vehicles_normalize
  before insert or update on public.vehicles
  for each row execute function public.vehicles_normalize();

create trigger vehicles_clamp_seats
  after update of passenger_seats on public.vehicles
  for each row execute function public.vehicles_clamp_seats();

-- Profiles ---------------------------------------------------------------------

-- Ride preferences rank matches and never filter them. No women-only and no
-- gender data (D-05).
alter table public.profiles
  add column ride_prefs text[] not null default '{}',
  add constraint profiles_ride_prefs_known check (
    ride_prefs <@ array['quiet','smoke_free']::text[]
    and (cardinality(ride_prefs) = 0 or array_ndims(ride_prefs) = 1)
  );

-- Function privileges ------------------------------------------------------------

-- Triggers fire without an execute check, so no client role needs these.
revoke execute on function public.commutes_normalize() from public, anon, authenticated;
revoke execute on function public.commutes_set_areas() from public, anon, authenticated;
revoke execute on function public.commutes_check_seats() from public, anon, authenticated;
revoke execute on function public.vehicles_normalize() from public, anon, authenticated;
revoke execute on function public.vehicles_clamp_seats() from public, anon, authenticated;

-- The commute trigger runs as the signed-in person and calls these, so they
-- stay executable by authenticated. None reveals anything: a random point near
-- a point you give, your own areas (RLS), or labels from public data.
revoke execute on function public.area_radius_m() from public, anon;
revoke execute on function public.within_area(extensions.geography, extensions.geography) from public, anon;
revoke execute on function public.random_area_center(extensions.geography) from public, anon;
revoke execute on function public.commute_area_for(uuid, uuid, extensions.geography, extensions.geography) from public, anon;
revoke execute on function public.area_label(extensions.geography) from public, anon;
grant execute on function public.area_radius_m() to authenticated;
grant execute on function public.within_area(extensions.geography, extensions.geography) to authenticated;
grant execute on function public.random_area_center(extensions.geography) to authenticated;
grant execute on function public.commute_area_for(uuid, uuid, extensions.geography, extensions.geography) to authenticated;
grant execute on function public.area_label(extensions.geography) to authenticated;
